'use strict';
const $=id=>document.getElementById(id);
const labels={confirmed:'漏洩を確認',possible:'漏洩の可能性',mixed:'確認済み・可能性あり',access:'権限外の閲覧を確認',denied:'続報で漏洩を否定',catalogue:'HIBP検証済み',announcement:'公式発表を確認・内容確認中',needsReview:'出典更新あり・再確認待ち'};
const state={records:[],tab:'all',page:1,pageSize:10,saved:new Set(),storage:true};
async function loadUpdateStatus(){const target=$('updateStatus');if(!target)return;try{const response=await fetch('update-status.json',{cache:'no-cache'});if(!response.ok)throw new Error('Status unavailable');const x=await response.json();const date=x.lastAttemptAt?new Intl.DateTimeFormat('ja-JP',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Tokyo'}).format(new Date(x.lastAttemptAt)):'未実行';const stale=x.lastAttemptAt&&(Date.now()-Date.parse(x.lastAttemptAt)>3*60*60*1000);const result=x.status==='complete'?'情報源を確認しました':x.status==='partial'?'一部の情報源を確認できませんでした（'+x.failedFetches+'件）':'情報源を確認できませんでした';target.textContent='前回の情報確認：'+date+' ／ '+result+(stale?'。確認日時が古くなっています。':'。')+'新着の発表は対象範囲や件数が確認中の場合があります。各社の公式案内もご確認ください。';}catch{target.textContent='情報の更新状況を取得できませんでした。最新の内容は各社の公式案内をご確認ください。';}}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).normalize('NFKC').toLocaleLowerCase('ja').trim();
const safeUrl=u=>{try{const x=new URL(u);return x.protocol==='https:'?x.href:'#'}catch{return '#'}};
const displayDate=s=>s?s.replaceAll('-','.'):'未公表';
let toastTimer;
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2800)}
function getSaved(){try{const ids=JSON.parse(localStorage.getItem('mofu-leakcheck-saved')||'[]');if(Array.isArray(ids))state.saved=new Set(ids.filter(id=>typeof id==='string'&&state.records.some(r=>r.id===id)))}catch{state.storage=false}}
function save(id){if(!state.records.some(r=>r.id===id))return;if(state.saved.has(id)){state.saved.delete(id);toast('「あとで確認」から外しました')}else{state.saved.add(id);toast(state.storage?'「あとで確認」に保存しました':'この画面の「あとで確認」に追加しました')}try{localStorage.setItem('mofu-leakcheck-saved',JSON.stringify([...state.saved]))}catch{state.storage=false;toast('保存機能が制限されています。この画面を開いている間だけ保持します。')}render();const target=[...document.querySelectorAll('[data-save]')].find(x=>x.dataset.save===id);if(target)target.focus({preventScroll:true})}
function badge(r){return `<span class="badge ${esc(r.status)}">${esc(labels[r.status]||'出典を確認')}</span>`}
function showNewMark(r){if(r.automaticallyCollected===true)return true;const latest=state.records.filter(x=>x.sourceType==='official'&&x.updated).reduce((m,x)=>x.updated>m?x.updated:m,'');return r.sourceType==='official'&&Boolean(latest)&&r.updated===latest}
function card(r){const saved=state.saved.has(r.id);return `<article class="incident" aria-labelledby="title-${esc(r.id)}"><div class="incident-top"><div><div class="company-line"><h3 id="title-${esc(r.id)}">${esc(r.company)}</h3><span class="category-tag">${esc(r.category)}</span></div><p class="service-title">${esc(r.service)}</p></div><button class="bookmark ${saved?'saved':''}" data-save="${esc(r.id)}" aria-pressed="${saved}" aria-label="${esc(r.service)}を${saved?'あとで確認から外す':'あとで確認に保存'}"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M5 2h10v16l-5-3-5 3Z"/></svg></button></div><div class="incident-sub">${badge(r)}${showNewMark(r)?'<span class="new-mark" aria-label="新着">NEW</span>':''}<span class="source-date">${r.sourceType==='hibp'?`事例発生日 ${esc(displayDate(r.eventDate))} ・ 海外サービス`:`公表 ${esc(displayDate(r.published))}${r.updated!==r.published?` ・ 資料更新 ${esc(displayDate(r.updated))}`:''}`}</span></div><div class="public-scale"><span class="field-label">公表されている件数・範囲</span><p>${esc(r.scale||"件数は未確認です。公式発表をご確認ください。")}</p></div><div class="impact-grid"><div class="audience"><span class="field-label">${r.status==='denied'?'続報の結論':'対象となる登録・利用（公表範囲）'}</span><p>${esc(r.audience)}</p></div><div class="data-block"><span class="field-label">${r.status==='denied'?'現在の公表状況':'公表資料に記載された情報項目'}</span><div class="tags">${r.items.length?r.items.map(t=>`<span class="tag">${esc(t)}</span>`).join(''):`<span class="tag">${r.status==='denied'?'漏洩はなかったと判断した旨を公表':'情報項目は未確認。出典本文をご確認ください。'}</span>`}</div></div></div>${r.excluded?`<p class="exclude"><b>${r.status==='denied'?'訂正内容：':'対象外・補足：'}</b>${esc(r.excluded)}</p>`:''}<div class="incident-foot"><span>${r.automaticallyCollected?'公式ページを自動取得':r.sourceChanged?'出典の再確認が必要':'資料確認 '+esc(displayDate(r.verifiedAt))}</span><div class="actions"><button class="textbtn" data-detail="${esc(r.id)}">対象条件・詳細</button><a class="source-link" href="${esc(safeUrl(r.source))}" target="_blank" rel="noopener noreferrer">${r.sourceType==='hibp'?'出典：HIBP':'公式発表を読む'} ↗</a></div></div></article>`}
function filtered(){const words=norm($('query').value).split(/[\s、,]+/).filter(Boolean);return state.records.filter(r=>{if(state.tab==='saved'&&!state.saved.has(r.id))return false;if(['official','hibp'].includes(state.tab)&&r.sourceType!==state.tab)return false;if($('category').value!=='all'&&r.category!==$('category').value)return false;if($('status').value!=='all'&&r.status!==$('status').value)return false;if($('dataType').value!=='all'&&!r.items.join(' ').includes($('dataType').value))return false;const text=norm([r.company,r.service,r.aliases,r.audience,...r.items].join(' '));return words.every(w=>text.includes(w))}).sort((a,b)=>$('sort').value==='name'?a.company.localeCompare(b.company,'ja'):b.updated.localeCompare(a.updated)||a.company.localeCompare(b.company,'ja'))}
function companyGroups(rs){const groups=new Map();for(const r of rs){const key=norm(r.company).replace(/株式会社|有限会社|[\s・（）()]/g,'');if(!groups.has(key))groups.set(key,{company:r.company,records:[]});groups.get(key).records.push(r)}return [...groups.values()]}
function needsOfficialReview(r){return r.automaticallyCollected===true||r.sourceChanged===true||r.status==='announcement'||r.status==='needsReview'}
function companyCard(g){
 const rs=[...g.records].sort((a,b)=>b.updated.localeCompare(a.updated));
 const latest=rs[0];
 const reviewed=rs.filter(r=>!r.automaticallyCollected);
 const primary=reviewed.length?reviewed:rs.slice(0,1);
 const items=[...new Set(primary.flatMap(r=>r.items))];
 const archive=rs.filter(r=>!primary.includes(r));
 const showItems=items.length>0||!primary.some(needsOfficialReview);
 return `<article class="company-group"><header class="company-group-head"><h2>${esc(g.company)}</h2><span>\u8cc7\u6599\u66f4\u65b0 ${esc(displayDate(latest.updated))}</span></header><div class="company-summary"><div class="incident-sub">${[...new Set(primary.map(r=>r.status))].map(status=>badge({status})).join('')}${rs.some(showNewMark)?'<span class="new-mark">\u65b0\u7740</span>':''}</div>${showItems?`<span class="field-label">\u516c\u8868\u8cc7\u6599\u306b\u8a18\u8f09\u3055\u308c\u305f\u60c5\u5831\u9805\u76ee</span><div class="tags">${items.length?items.map(t=>`<span class="tag">${esc(t)}</span>`).join(''):'\u60c5\u5831\u9805\u76ee\u306f\u672a\u78ba\u8a8d'}</div>`:''}<div class="scope-list">${primary.map(r=>{
  const pending=needsOfficialReview(r);
  const sourceUrl=safeUrl(r.source);
  const showOfficialLink=pending&&r.sourceType==='official'&&sourceUrl!=='#';
  const summary=r.automaticallyCollected?'\u516c\u5f0f\u767a\u8868\u3092\u81ea\u52d5\u53d6\u5f97\u3057\u305f\u6bb5\u968e\u3067\u3059\u3002\u5f71\u97ff\u3092\u53d7\u3051\u305f\u767b\u9332\u30fb\u5229\u7528\u6761\u4ef6\u3084\u60c5\u5831\u9805\u76ee\u306f\u3001\u307e\u3060\u78ba\u8a8d\u3067\u304d\u3066\u3044\u307e\u305b\u3093\u3002':r.sourceChanged?'\u51fa\u5178\u306b\u66f4\u65b0\u304c\u3042\u308a\u3001\u63b2\u8f09\u5185\u5bb9\u3092\u518d\u78ba\u8a8d\u4e2d\u3067\u3059\u3002\u6700\u65b0\u306e\u5bfe\u8c61\u7bc4\u56f2\u306f\u516c\u5f0f\u767a\u8868\u3092\u3054\u78ba\u8a8d\u304f\u3060\u3055\u3044\u3002':pending?'\u516c\u5f0f\u767a\u8868\u3092\u78ba\u8a8d\u3057\u307e\u3057\u305f\u304c\u3001\u63b2\u8f09\u5185\u5bb9\u306f\u78ba\u8a8d\u4e2d\u3067\u3059\u3002\u5bfe\u8c61\u6761\u4ef6\u3084\u60c5\u5831\u9805\u76ee\u306f\u516c\u5f0f\u767a\u8868\u3067\u3054\u78ba\u8a8d\u304f\u3060\u3055\u3044\u3002':r.audience;
  const count=r.automaticallyCollected?'\u4ef6\u6570\u30fb\u5bfe\u8c61\u7bc4\u56f2\u306f\u672a\u78ba\u8a8d':r.sourceChanged?'\u516c\u8868\u4ef6\u6570\u30fb\u5bfe\u8c61\u7bc4\u56f2\u3092\u518d\u78ba\u8a8d\u4e2d':(r.scale||'\u516c\u8868\u4ef6\u6570\u306f\u78ba\u8a8d\u3067\u304d\u3066\u3044\u307e\u305b\u3093\u3002\u516c\u5f0f\u767a\u8868\u3092\u3054\u78ba\u8a8d\u304f\u3060\u3055\u3044\u3002');
  const note=r.automaticallyCollected?'<p class="unconfirmed-note">\u3053\u306e\u63b2\u8f09\u3060\u3051\u3067\u306f\u3001\u60c5\u5831\u6f0f\u3048\u3044\u306e\u6709\u7121\u3084\u3054\u81ea\u8eab\u304c\u5bfe\u8c61\u304b\u3069\u3046\u304b\u306f\u5224\u65ad\u3067\u304d\u307e\u305b\u3093\u3002</p>':r.sourceChanged?'<p class="unconfirmed-note">\u66f4\u65b0\u5f8c\u306e\u5185\u5bb9\u3068\u6700\u65b0\u306e\u5bfe\u8c61\u7bc4\u56f2\u306f\u3001\u516c\u5f0f\u767a\u8868\u3067\u3054\u78ba\u8a8d\u304f\u3060\u3055\u3044\u3002</p>':pending?'<p class="unconfirmed-note">\u3053\u306e\u63b2\u8f09\u3060\u3051\u3067\u306f\u3001\u3054\u81ea\u8eab\u304c\u5bfe\u8c61\u304b\u3069\u3046\u304b\u306f\u5224\u65ad\u3067\u304d\u307e\u305b\u3093\u3002</p>':'';
  return `<section class="scope-row"><div class="scope-main"><h3>${esc(r.service)}</h3><p>${esc(summary)}</p>${note}${r.excluded?`<p class="scope-note">\u5bfe\u8c61\u5916\u30fb\u88dc\u8db3\uff1a${esc(r.excluded)}</p>`:''}</div><div class="scope-count"><span class="field-label">\u516c\u8868\u4ef6\u6570\u30fb\u7bc4\u56f2</span><p>${esc(count)}</p>${showOfficialLink?`<a class="official-source-cta" href="${esc(sourceUrl)}" target="_blank" rel="noopener noreferrer">\u516c\u5f0f\u30b5\u30a4\u30c8\u3067\u767a\u8868\u3092\u78ba\u8a8d <span aria-hidden="true">&#8599;</span></a><p class="official-source-help">\u767a\u8868\u5143\u306e\u30da\u30fc\u30b8\u304c\u5225\u30bf\u30d6\u3067\u958b\u304d\u307e\u3059\u3002\u6700\u65b0\u306e\u5bfe\u8c61\u7bc4\u56f2\u306f\u516c\u5f0f\u767a\u8868\u3067\u3054\u78ba\u8a8d\u304f\u3060\u3055\u3044\u3002</p>`:''}<button class="textbtn" data-detail="${esc(r.id)}">\u5bfe\u8c61\u6761\u4ef6\u30fb\u51fa\u5178\u3092\u78ba\u8a8d</button><button class="textbtn" data-save="${esc(r.id)}">${state.saved.has(r.id)?'\u4fdd\u5b58\u6e08\u307f':'\u3042\u3068\u3067\u78ba\u8a8d'}</button></div></section>`
 }).join('')}</div><p class="fine">\u30b5\u30fc\u30d3\u30b9\u30fb\u533a\u5206\u306b\u3088\u3063\u3066\u5bfe\u8c61\u306e\u60c5\u5831\u9805\u76ee\u306f\u7570\u306a\u308a\u307e\u3059\u3002\u4ef6\u6570\u306f\u91cd\u8907\u3059\u308b\u53ef\u80fd\u6027\u304c\u3042\u308b\u305f\u3081\u5408\u7b97\u3057\u3066\u3044\u307e\u305b\u3093\u3002</p>${archive.length?`<details class="company-archive"><summary>\u95a2\u9023\u3059\u308b\u767a\u8868\u30fb\u7d9a\u5831\uff08${archive.length}\u4ef6\uff09</summary>${archive.map(r=>`<div class="archive-row"><span>${esc(displayDate(r.updated))}</span><button class="textbtn" data-detail="${esc(r.id)}">${esc(r.service)}</button></div>`).join('')}</details>`:''}</div></article>`
}
function render(){const rs=filtered();const groups=companyGroups(rs);const totalPages=Math.max(1,Math.ceil(groups.length/state.pageSize));state.page=Math.min(state.page,totalPages);const start=(state.page-1)*state.pageSize;const visible=groups.slice(start,start+state.pageSize);$('allCount').textContent=state.records.length;$('globalCount').textContent=state.records.filter(r=>r.sourceType==='hibp').length;document.querySelector('[data-tab="hibp"]').hidden=state.records.every(r=>r.sourceType!=='hibp');$('savedCount').textContent=state.saved.size;$('resultCount').textContent=`${groups.length}社・${rs.length}件の掲載情報${groups.length?' ・ '+Math.min(start+1,groups.length)+'〜'+Math.min(start+state.pageSize,groups.length)+'社を表示中':''}`;$('list').innerHTML=visible.map(companyCard).join('');$('empty').hidden=rs.length>0;$('page-status').textContent=groups.length?`${start+1}〜${Math.min(start+state.pageSize,groups.length)}社 ／ 全${groups.length}社`:'該当する企業はありません';$('page-current').textContent=`${state.page} / ${totalPages}`;$('prev').disabled=state.page<=1;$('next').disabled=state.page>=totalPages;$('coverage').textContent=state.tab==='hibp'?'日本でも利用される海外サービスの直近3年の事例です。出典：Have I Been Pwned（CC BY 4.0）。日本の利用者の対象人数は確認できていません。':state.tab==='saved'?'保存されるのは事例のIDだけです。個人情報の漏洩判定をした結果ではありません。':'直近3年に公式発表・続報があった情報を掲載。ニュースから公式発表を探しますが、すべての事故・企業を網羅した一覧ではありません。';document.querySelectorAll('[data-tab]').forEach(b=>{const on=b.dataset.tab===state.tab;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))})}
function reset(){state.tab='all';state.page=1;['query'].forEach(id=>$(id).value='');['category','status','dataType'].forEach(id=>$(id).value='all');render()}
function detail(id,updateHash=true){const r=state.records.find(x=>x.id===id);if(!r)return;$('detailContent').innerHTML=`${badge(r)}<h2>${esc(r.company)}</h2><p>${esc(r.service)}</p><p class="detail-dates">${r.sourceType==='hibp'?`HIBPの事例発生日：${esc(displayDate(r.eventDate))} ／ HIBP収録日：${esc(displayDate(r.published))}`:`初回公表日：${esc(displayDate(r.published))} ／ 参照資料更新日：${esc(displayDate(r.updated))}`}<br>${r.automaticallyCollected?'公式発表を確認中です。対象や件数は、リンク先の最新案内をご確認ください。':r.sourceChanged?'旧要約の確認日：'+esc(displayDate(r.verifiedAt))+'（出典更新のため再確認待ち）':'資料確認日：'+esc(displayDate(r.verifiedAt))}</p><h3>どんな登録・利用が対象？</h3><p class="detail-scope">${esc(r.automaticallyCollected?'対象となる登録・利用条件は確認中です。公式発表で最新の内容をご確認ください。':r.audience)}</p><h3>公表資料に記載された情報項目</h3><p>${r.items.map(esc).join('、')||(r.status==='denied'?'続報で漏洩はなかったと判断したとの報告を受けたと公表しています。':r.automaticallyCollected?'公表資料の確認中です。公式発表をご確認ください。':'この項目は確認していません。出典の本文をご確認ください。')}</p><h3>公表されている件数・範囲</h3><p>${esc(r.automaticallyCollected?'件数・対象条件はまだ確認できていません。詳細と最新状況は公式発表をご確認ください。':(r.scale||'公表件数は確認できていません。公式発表をご確認ください。'))}</p><p class="fine">件数・人数・アカウント数は出典の単位を保っています。項目や区分の件数を合算した被害人数には置き換えていません。</p><h3>確認されていること・留意する点</h3><p>${esc(r.automaticallyCollected?'公式発表を自動取得した段階です。対象条件、件数、情報項目は確認中です。最新情報は公式発表をご確認ください。':r.note)}</p>${r.excluded?`<h3>対象外・補足</h3><p>${esc(r.excluded)}</p>`:''}<p class="facts">この事例の公表条件と、ご自身の登録・利用履歴を照らし合わせてください。個人の情報が実際に漏洩したかは、このサイトでは判定できません。</p><a class="source-link" href="${esc(safeUrl(r.source))}" target="_blank" rel="noopener noreferrer">${r.sourceType==='hibp'?'Have I Been Pwnedの事例ページを開く':'企業等の公式発表・案内を開く'} ↗</a>${(r.additionalSources||[]).map(u=>`<br><a class="source-link" href="${esc(safeUrl(u))}" target="_blank" rel="noopener noreferrer">あわせて参照した公式発表 ↗</a>`).join('')}${r.originalDescription?`<h3>出典の原文（英語）</h3><p class="original" lang="en">${esc(r.originalDescription)}</p><p class="fine">Data from <a href="https://haveibeenpwned.com/" target="_blank" rel="noopener noreferrer">Have I Been Pwned</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. 日本語の対象条件・情報項目はこのデータに基づく要約です。</p>`:''}`;if(!$('detail').open)$('detail').showModal();$('detail').scrollTop=0;if(updateHash)history.replaceState(null,'','#'+encodeURIComponent(id))}
async function load(){try{$('loadError').hidden=true;const response=await fetch('incidents.json',{cache:'no-cache'});if(!response.ok)throw new Error('HTTP '+response.status);const data=await response.json();if(!Array.isArray(data.incidents))throw new Error('Invalid catalogue');state.records=data.incidents;const opts=[...new Set(state.records.map(x=>x.category))].sort((a,b)=>a.localeCompare(b,'ja'));$('category').innerHTML='<option value="all">すべてのジャンル</option>'+opts.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');getSaved();render();await loadUpdateStatus();if(location.hash){let id;try{id=decodeURIComponent(location.hash.slice(1))}catch{}if(id)detail(id,false)}}catch(err){$('list').innerHTML='';$('resultCount').textContent='一覧を表示できませんでした';$('loadError').hidden=false;$('next').disabled=true;console.error('Catalogue could not be loaded',err)}}
$('searchForm').addEventListener('submit',e=>{e.preventDefault();state.page=1;render();$('results').scrollIntoView({behavior:'smooth'})});$('query').addEventListener('input',()=>{state.page=1;render()});document.querySelectorAll('[data-query]').forEach(b=>b.addEventListener('click',()=>{reset();$('query').value=b.dataset.query;render();$('results').scrollIntoView({behavior:'smooth'})}));document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{state.tab=b.dataset.tab;state.page=1;render()}));['category','status','dataType','sort'].forEach(id=>$(id).addEventListener('change',()=>{state.page=1;render()}));$('reset').addEventListener('click',reset);$('emptyReset').addEventListener('click',reset);$('page-size').addEventListener('change',e=>{state.pageSize=Math.min(50,Math.max(10,Number(e.target.value)||10));state.page=1;render()});$('prev').addEventListener('click',()=>{if(state.page>1){state.page--;render();$('results').scrollIntoView({behavior:'smooth'})}});$('next').addEventListener('click',()=>{state.page++;render();$('results').scrollIntoView({behavior:'smooth'})});$('retry').addEventListener('click',load);$('list').addEventListener('click',e=>{const b=e.target.closest('[data-detail],[data-save]');if(!b)return;if(b.dataset.detail)detail(b.dataset.detail);else if(b.dataset.save)save(b.dataset.save)});$('detail').querySelector('.close').addEventListener('click',()=>$('detail').close());$('detail').addEventListener('close',()=>history.replaceState(null,'',location.pathname+location.search));$('detail').addEventListener('click',e=>{if(e.target===$('detail')){const rect=$('detail').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)$('detail').close()}});window.addEventListener('hashchange',()=>{if(location.hash){try{detail(decodeURIComponent(location.hash.slice(1)),false)}catch{}}else if($('detail').open)$('detail').close()});load();



